import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { LockfileError, parseLockfile } from '../src/core/parsers';

const fixture = (name: string) =>
  readFileSync(new URL(`./fixtures/${name}`, import.meta.url), 'utf8');

// All fixtures were generated by the real package managers from the same package.json:
// lodash 4.17.15, minimist 1.2.5, left-pad 1.3.0, @babel/code-frame 7.12.13,
// string-width-cjs → npm:string-width@4.2.3, esbuild 0.19.12, dev: is-number 7.0.0
const DIRECT = [
  '@babel/code-frame@7.12.13',
  'esbuild@0.19.12',
  'is-number@7.0.0',
  'left-pad@1.3.0',
  'lodash@4.17.15',
  'minimist@1.2.5',
  'string-width@4.2.3',
];

const CASES = [
  {
    file: 'package-lock.v3.json',
    name: 'package-lock.json',
    format: 'npm',
    version: '3',
    direct: true,
  },
  {
    file: 'package-lock.v1.json',
    name: 'package-lock.json',
    format: 'npm',
    version: '1',
    direct: false,
  },
  {
    file: 'pnpm-lock.v9.yaml',
    name: 'pnpm-lock.yaml',
    format: 'pnpm',
    version: '9.0',
    direct: true,
  },
  {
    file: 'pnpm-lock.v6.yaml',
    name: 'pnpm-lock.yaml',
    format: 'pnpm',
    version: '6.0',
    direct: true,
  },
  {
    file: 'pnpm-lock.v5.yaml',
    name: 'pnpm-lock.yaml',
    format: 'pnpm',
    version: '5.4',
    direct: true,
  },
  {
    file: 'yarn-classic.lock',
    name: 'yarn.lock',
    format: 'yarn-classic',
    version: '1',
    direct: false,
  },
  { file: 'yarn-berry.lock', name: 'yarn.lock', format: 'yarn-berry', version: '8', direct: true },
  { file: 'bun.lock', name: 'bun.lock', format: 'bun', version: '1', direct: true },
] as const;

describe.each(CASES)('$file', ({ file, name, format, version, direct }) => {
  const text = fixture(file);

  it('detects the format from the file name', () => {
    const parsed = parseLockfile(text, name);
    expect(parsed.format).toBe(format);
    expect(parsed.lockfileVersion).toBe(version);
  });

  it('detects the format from content alone (pasted text)', () => {
    expect(parseLockfile(text).format).toBe(format);
  });

  it('resolves the same 45 registry packages as every other format', () => {
    const parsed = parseLockfile(text, name);
    expect(parsed.packages).toHaveLength(45);
    const keys = parsed.packages.map((p) => `${p.name}@${p.version}`);
    for (const key of DIRECT) expect(keys).toContain(key);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it('resolves the npm: alias to the real package name', () => {
    const parsed = parseLockfile(text, name);
    expect(parsed.packages.some((p) => p.name === 'string-width-cjs')).toBe(false);
    expect(parsed.packages.some((p) => p.name === 'string-width' && p.version === '4.2.3')).toBe(
      true,
    );
  });

  if (direct) {
    it('marks exactly the direct dependencies', () => {
      const parsed = parseLockfile(text, name);
      const marked = parsed.packages.filter((p) => p.direct).map((p) => `${p.name}@${p.version}`);
      expect(marked.sort()).toEqual([...DIRECT].sort());
    });
  }
});

describe('format specifics', () => {
  it('npm v3: reads install scripts and dev flags', () => {
    const parsed = parseLockfile(fixture('package-lock.v3.json'), 'package-lock.json');
    const esbuild = parsed.packages.find((p) => p.name === 'esbuild');
    expect(esbuild?.hasInstallScript).toBe(true);
    expect(parsed.packages.find((p) => p.name === 'is-number')?.dev).toBe(true);
    expect(parsed.packages.find((p) => p.name === 'lodash')?.dev).toBe(false);
  });

  it('pnpm v6: reads requiresBuild and dev flags', () => {
    const parsed = parseLockfile(fixture('pnpm-lock.v6.yaml'), 'pnpm-lock.yaml');
    expect(parsed.packages.find((p) => p.name === 'esbuild')?.hasInstallScript).toBe(true);
    expect(parsed.packages.find((p) => p.name === 'is-number')?.dev).toBe(true);
  });

  it('pnpm v9: infers dev for direct dev dependencies', () => {
    const parsed = parseLockfile(fixture('pnpm-lock.v9.yaml'), 'pnpm-lock.yaml');
    expect(parsed.packages.find((p) => p.name === 'is-number')?.dev).toBe(true);
    expect(parsed.packages.find((p) => p.name === 'lodash')?.dev).toBe(false);
  });

  it('bun: marks dev-only direct dependencies', () => {
    const parsed = parseLockfile(fixture('bun.lock'), 'bun.lock');
    expect(parsed.packages.find((p) => p.name === 'is-number')?.dev).toBe(true);
  });

  it('yarn berry: skips the workspace entry', () => {
    const parsed = parseLockfile(fixture('yarn-berry.lock'), 'yarn.lock');
    expect(parsed.skipped).toEqual([
      expect.objectContaining({ name: 'fixture-app', reason: 'workspace package' }),
    ]);
  });
});

describe('non-registry dependencies', () => {
  it('npm: skips links, git and file dependencies', () => {
    const lock = {
      lockfileVersion: 3,
      packages: {
        '': { dependencies: { a: '1.0.0', b: 'github:x/b', c: 'file:../c', ws: '*' } },
        'node_modules/a': {
          version: '1.0.0',
          resolved: 'https://registry.npmjs.org/a/-/a-1.0.0.tgz',
        },
        'node_modules/b': { version: '2.0.0', resolved: 'git+ssh://git@github.com/x/b.git#abc' },
        'node_modules/c': { version: '0.0.1', resolved: 'file:../c' },
        'node_modules/ws': { resolved: 'packages/ws', link: true },
        'packages/ws': { name: 'ws', version: '0.0.0' },
        'node_modules/a/node_modules/d': { version: '3.0.0' },
      },
    };
    const parsed = parseLockfile(JSON.stringify(lock), 'package-lock.json');
    expect(parsed.packages.map((p) => `${p.name}@${p.version}`)).toEqual(['a@1.0.0', 'd@3.0.0']);
    expect(parsed.packages.find((p) => p.name === 'a')?.direct).toBe(true);
    expect(parsed.packages.find((p) => p.name === 'd')?.direct).toBe(false);
    expect(parsed.skipped.map((s) => s.reason).sort()).toEqual([
      'git dependency',
      'local file dependency',
      'workspace link',
    ]);
  });

  it('yarn berry: resolves patched packages to the package they patch', () => {
    const text = [
      '__metadata:',
      '  version: 8',
      '',
      '"resolve@patch:resolve@npm%3A^1.22.0#optional!builtin<compat/resolve>":',
      '  version: 1.22.8',
      '  resolution: "resolve@patch:resolve@npm%3A1.22.8#optional!builtin<compat/resolve>::version=1.22.8&hash=c3c19d"',
      '',
      '"foo@https://example.com/foo.tgz":',
      '  version: 1.0.0',
      '  resolution: "foo@https://example.com/foo.tgz"',
      '',
    ].join('\n');
    const parsed = parseLockfile(text, 'yarn.lock');
    expect(parsed.packages).toEqual([
      expect.objectContaining({ name: 'resolve', version: '1.22.8' }),
    ]);
    expect(parsed.skipped).toHaveLength(1);
  });

  it('yarn classic: skips git and tarball URL entries', () => {
    const text = [
      '# yarn lockfile v1',
      '',
      '"@scope/pkg@^1.0.0":',
      '  version "1.2.3"',
      '  resolved "https://registry.yarnpkg.com/@scope/pkg/-/pkg-1.2.3.tgz#abc"',
      '',
      'gitdep@github:x/gitdep:',
      '  version "0.1.0"',
      '  resolved "https://codeload.github.com/x/gitdep/tar.gz/abc"',
      '',
    ].join('\n');
    const parsed = parseLockfile(text, 'yarn.lock');
    expect(parsed.packages).toEqual([
      expect.objectContaining({ name: '@scope/pkg', version: '1.2.3' }),
    ]);
    expect(parsed.skipped).toHaveLength(1);
  });

  it('pnpm v9: skips git and directory resolutions', () => {
    const text = [
      "lockfileVersion: '9.0'",
      'importers:',
      '  .:',
      '    dependencies:',
      '      a:',
      '        specifier: ^1.0.0',
      '        version: 1.0.0',
      'packages:',
      '  a@1.0.0:',
      '    resolution: {integrity: sha512-x}',
      '  b@https://codeload.github.com/x/b/tar.gz/abc:',
      '    resolution: {tarball: https://codeload.github.com/x/b/tar.gz/abc}',
      '    version: 2.0.0',
      '  c@file:../c:',
      '    resolution: {directory: ../c, type: directory}',
      'snapshots:',
      '  a@1.0.0: {}',
    ].join('\n');
    const parsed = parseLockfile(text, 'pnpm-lock.yaml');
    expect(parsed.packages).toEqual([
      expect.objectContaining({ name: 'a', version: '1.0.0', direct: true }),
    ]);
    expect(parsed.skipped).toHaveLength(2);
  });
});

describe('invalid input', () => {
  it('rejects an empty file', () => {
    expect(() => parseLockfile('   ', 'package-lock.json')).toThrow(LockfileError);
  });

  it('explains that package.json is not a lockfile', () => {
    const pkg = JSON.stringify({ name: 'x', dependencies: { a: '^1.0.0' } });
    expect(() => parseLockfile(pkg, 'package.json')).toThrow(/version ranges/);
    expect(() => parseLockfile(pkg)).toThrow(/version ranges/);
  });

  it('explains how to convert binary bun.lockb', () => {
    expect(() => parseLockfile('\u0000\u0001bun', 'bun.lockb')).toThrow(/save-text-lockfile/);
  });

  it('reports invalid JSON', () => {
    expect(() => parseLockfile('{"lockfileVersion": 3,', 'package-lock.json')).toThrow(
      /Invalid JSON/,
    );
  });

  it('rejects unrecognised text', () => {
    expect(() => parseLockfile('hello world, this is not a lockfile')).toThrow(
      /Unrecognised lockfile/,
    );
  });

  it('handles a byte-order mark', () => {
    const parsed = parseLockfile(
      String.fromCharCode(0xfeff) + fixture('package-lock.v3.json'),
      'package-lock.json',
    );
    expect(parsed.packages).toHaveLength(45);
  });
});
